SELECT patients.name
FROM patients
WHERE NOT EXISTS (SELECT 1 FROM appointments WHERE appointments.patient_id = patients.patient_id);

SELECT full_name, consultation_fee
FROM doctors
WHERE consultation_fee > (SELECT AVG(consultation_fee) FROM doctors);

UPDATE medicines
SET unit_price = unit_price * 1.20
WHERE unit_price < 10;

SELECT *
FROM patients
WHERE city IS NULL;

DELIMITER $$
CREATE PROCEDURE GetPatientsByCity(IN p_value VARCHAR(30))
BEGIN
  SELECT * FROM patients WHERE city = p_value;
END $$
DELIMITER ;
